package me.pikanote.companion;
import android.app.Instrumentation;import android.content.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.json.*;
final class OfflineInboxChecks{
 static void check(boolean ok,String reason)throws Exception{if(!ok)throw new Exception(reason);}
 static JSONObject operation(String kind,String action,String id,String text)throws Exception{return new JSONObject().put("kind",kind).put("action",action).put("id",id).put("record",new JSONObject().put("text",text).put("date","").put("end","").put("done",true).put("archived",true).put("allDay",false).put("priority","normal"));}
 static void queued(Store s,int seq)throws Exception{String stem=String.format(Locale.ROOT,"askq_%010d_1234abcd",seq);Files.write(s.safeFile(stem+".wav").toPath(),new byte[16044]);Files.write(s.safeFile(stem+".json").toPath(),new JSONObject().put("sequence",seq).put("audio",stem+".wav").put("capturedUtc","2026-10-30T10:00:00Z").toString().getBytes(StandardCharsets.UTF_8));}
 static void livePlanner(Instrumentation i)throws Exception{String key=PhoneVoice.key(Store.get(i.getTargetContext()));check(!key.isEmpty(),"AI key unavailable for isolated planner check");JSONObject snapshot=new JSONObject("{\"memories\":[],\"tasks\":[],\"events\":[]}");snapshot.getJSONArray("memories").put(new JSONObject().put("id","m1").put("text","Завтра купить хлеб. Завтра в 19:30 совещание.").put("archived",false));JSONObject a=OfflineInbox.plan("Сколько будет дважды два?","2026-10-30T10:00:00Z",snapshot,key);check(a.getString("type").equals("conversation")&&a.getJSONArray("operations").length()==0,"Conversation classified as mutation");JSONObject b=OfflineInbox.plan("Создай задачи и событие из моей единственной заметки","2026-10-30T10:00:00Z",snapshot,key);check(b.getString("type").equals("command")&&b.getJSONArray("operations").length()>=2,"Memory planning failed");boolean task=false,event=false;JSONArray ops=b.getJSONArray("operations");for(int n=0;n<ops.length();n++){JSONObject op=ops.getJSONObject(n);task|=op.getString("kind").equals("tasks");event|=op.getString("kind").equals("events")&&op.getJSONObject("record").optString("date").startsWith("2026-10-31T19:30");}check(task&&event,"Captured date or extraction wrong: "+b.toString());}
 static void run(Instrumentation i)throws Exception{Context real=i.getTargetContext();File root=new File(real.getFilesDir(),"offline-inbox-check");Context sandbox=new ContextWrapper(real){public File getFilesDir(){root.mkdirs();return root;}};PhoneBackup.remove(root);try{Store s=new Store(sandbox);
 check(PlannedDates.currentMonthDate("Create event on 28 this month","2026-11-03").equals("2026-11-28"),"Current month anchor incorrect");
 JSONObject dateOp=operation("events","save","","Village internet");dateOp.getJSONObject("record").put("date","2026-11-28T00:00:00").put("end","2026-11-28T23:59:59").put("allDay",true);
 JSONObject datePlan=new JSONObject().put("type","command").put("operations",new JSONArray().put(dateOp));OfflineInbox.normalize(s,datePlan);OfflineInbox.validate(s,datePlan);check(dateOp.getJSONObject("record").getString("date").equals("2026-11-28")&&dateOp.getJSONObject("record").getString("end").equals("2026-11-28"),"All-day boundaries not normalized");
 dateOp.getJSONObject("record").put("date","2026-02-30").put("end","2026-02-30");boolean invalidDate=false;try{OfflineInbox.validate(s,datePlan);}catch(IOException expected){invalidDate=true;}check(invalidDate,"Impossible all-day date accepted");
 dateOp.getJSONObject("record").put("date","2026-11-28").put("end","2026-11-27");invalidDate=false;try{OfflineInbox.validate(s,datePlan);}catch(IOException expected){invalidDate=true;}check(invalidDate,"Reversed all-day range accepted");
 queued(s,2);queued(s,1);OfflineInbox.discover(s);int[] called={0};OfflineInbox.Planner conversation=(q,date,snap,key)->new JSONObject().put("type","conversation").put("summary","Ignored").put("operations",new JSONArray());OfflineInbox.processOne(s,(f,k)->{check(f.getName().contains("0000000001"),"Not oldest first");called[0]++;return "Сколько дважды два?";},conversation);check(s.snapshot().getJSONArray("tasks").length()==0,"Conversation mutated records");check(OfflineInbox.jobs(s).getJSONObject(0).getString("status").equals("ignored"),"Conversation not ignored");
 OfflineInbox.Planner create=(q,date,snap,key)->new JSONObject().put("type","command").put("summary","Created").put("operations",new JSONArray().put(operation("tasks","save","","Fixture task")));OfflineInbox.processOne(s,(f,k)->{called[0]++;return "Создай задачу";},create);check(s.snapshot().getJSONArray("tasks").length()==1,"Command not applied");int pending=s.state.getJSONArray("pending").length();Store reload=new Store(sandbox);OfflineInbox.discover(reload);OfflineInbox.processOne(reload,(f,k)->{throw new Exception("Duplicate transcription");},create);check(reload.state.getJSONArray("pending").length()==pending,"Restart duplicated command");
 queued(reload,3);queued(reload,4);OfflineInbox.discover(reload);OfflineInbox.processOne(reload,(f,k)->{throw new IOException("fixture network failure");},create);OfflineInbox.processOne(reload,(f,k)->{throw new Exception("Younger request overtook failed request");},create);check(reload.snapshot().getJSONArray("tasks").length()==1,"Ordering failed after error");
 JSONObject task=reload.snapshot().getJSONArray("tasks").getJSONObject(0);JSONObject normalized=new JSONObject().put("type","command").put("operations",new JSONArray().put(operation("tasks","delete",task.getString("id"),task.getString("text"))));OfflineInbox.normalize(reload,normalized);check(normalized.getJSONArray("operations").getJSONObject(0).getString("action").equals("toggle"),"Task delete was not completion");
 // Source memory: a manual edit during the provider call must win.
 JSONObject snap=reload.snapshot();snap.getJSONArray("memories").put(new JSONObject().put("id","m7").put("text","").put("wav",true).put("archived",false).put("date","2026-10-30T12:00"));reload.state.put("snapshot",snap);Files.write(reload.safeFile("note_007.wav").toPath(),new byte[16044]);OfflineInbox.discover(reload);check(PhoneVoice.jobs(reload).length()==1,"Device WAV was not queued");PhoneVoice.processOne(reload,(f,k)->{reload.queueMutation(operation("memories","save","m7","Ручная правка"));return "Automatic must not win";});check(reload.find(reload.snapshot(),"memories","m7").getString("text").equals("Ручная правка"),"Automatic transcription overwrote manual edit");check(PhoneVoice.jobs(reload).getJSONObject(0).getString("status").equals("manual"),"Manual job not suppressed");
 // Another blank memory gets updated in place, never duplicated or re-uploaded as a new WAV.
 snap=reload.snapshot();snap.getJSONArray("memories").put(new JSONObject().put("id","m8").put("text","").put("wav",true).put("archived",false).put("date","2026-10-30T12:01"));reload.state.put("snapshot",snap);Files.write(reload.safeFile("note_008.wav").toPath(),new byte[16044]);OfflineInbox.discover(reload);PhoneVoice.processOne(reload,(f,k)->"Новая расшифровка");check(reload.snapshot().getJSONArray("memories").length()==2,"Offline memory duplicated");check(reload.find(reload.snapshot(),"memories","m8").getString("text").equals("Новая расшифровка"),"Transcript not applied");check(!PhoneVoice.hasUploads(reload),"Device WAV queued for redundant upload");
 }finally{PhoneBackup.remove(root);}}
}
